<div class="studio-fields-two"><div class="studio-field"><label>Rótulo</label><input name="label" required maxlength="120" value="<?= $this->e($item['label']??'') ?>"></div><div class="studio-field"><label>Tipo</label><select name="type"><option value="page"<?= ($item['type']??'page')==='page'?' selected':'' ?>>Página interna</option><option value="external"<?= ($item['type']??'')==='external'?' selected':'' ?>>URL externa</option></select></div><div class="studio-field"><label>Página</label><select name="page_id"><option value="">Selecione</option><?php foreach($pages as $page):?><option value="<?= (int)$page['id'] ?>"<?= (int)($item['page_id']??0)===(int)$page['id']?' selected':'' ?>><?= $this->e($page['title']) ?></option><?php endforeach;?></select></div><div class="studio-field"><label>URL externa</label><input type="url" name="url" maxlength="500" placeholder="https://..." value="<?= $this->e($item['url']??'') ?>"></div><div class="studio-field"><label>Item pai</label><select name="parent_id"><option value="">Nenhum</option><?php foreach($items as $parent):?><?php if((int)$parent['id']!==(int)($item['id']??0)):?><option value="<?= (int)$parent['id'] ?>"<?= (int)($item['parent_id']??0)===(int)$parent['id']?' selected':'' ?>><?= $this->e($parent['label']) ?></option><?php endif;?><?php endforeach;?></select></div><div class="studio-field"><label>Ordem</label><input type="number" name="position" min="0" max="9999" value="<?= (int)($item['position']??0) ?>"></div><div class="studio-field"><label>Destino</label><select name="target"><option value="_self"<?= ($item['target']??'_self')==='_self'?' selected':'' ?>>Mesma aba</option><option value="_blank"<?= ($item['target']??'')==='_blank'?' selected':'' ?>>Nova aba</option></select></div><div class="studio-field"><label>Status</label><select name="status"><option value="active"<?= ($item['status']??'active')==='active'?' selected':'' ?>>Ativo</option><option value="inactive"<?= ($item['status']??'')==='inactive'?' selected':'' ?>>Inativo</option></select></div></div>
